import type { Metadata } from "next";
import Link from "next/link";
import { startGuestPractice } from "@/app/practice/actions";
import { PublicFooter } from "@/components/public-footer";
import { PublicHeader } from "@/components/public-header";
import { getCurrentUser } from "@/lib/auth/session";
import { getPreferences } from "@/lib/i18n/get-translations";

export const metadata: Metadata = {
  title: "Thử luyện TOEIC miễn phí",
  description: "Thử bài luyện TOEIC Listening và Reading miễn phí, xem kết quả theo từng Part và biết phần nào cần ôn tiếp.",
  alternates: { canonical: "/try" },
};

export default async function TryPage({ searchParams }: PageProps<"/try">) { const [user, query] = await Promise.all([getCurrentUser(), searchParams]); const locale = (await getPreferences(user?.id)).interfaceLanguage; const vi = locale === "vi"; const choices = [{ kind: "listening", title: vi ? "Thử Listening" : "Try Listening", meta: vi ? "~9 câu · ~7 phút" : "~9 questions · ~7 minutes", body: vi ? "Làm trọn nhóm Part 3 và xem phần Listening nào cần chú ý." : "Complete a Part 3 group and see where Listening needs attention." }, { kind: "reading", title: vi ? "Thử Reading" : "Try Reading", meta: vi ? "~10 câu · ~8 phút" : "~10 questions · ~8 minutes", body: vi ? "Làm bài Reading ngắn và xem Part nào cần luyện thêm." : "Take a short Reading set and identify the Part to practice next." }] as const; return <main className="min-h-screen bg-slate-50 text-slate-900"><PublicHeader locale={locale} signedIn={Boolean(user)} /><div className="mx-auto max-w-5xl px-5 py-10 sm:px-6 sm:py-16"><p className="text-sm font-black uppercase tracking-[.16em] text-teal-700">{vi ? "Không cần tài khoản" : "No account required"}</p><h1 className="mt-3 text-4xl font-black sm:text-5xl">{vi ? "Khám phá điểm cần cải thiện" : "Find your next area to improve"}</h1><p className="mt-4 max-w-2xl text-lg leading-8 text-slate-600">{vi ? "Bắt đầu với bài đánh giá được đề xuất, hoặc thử ngay một bài ngắn. Bạn sẽ nhận kết quả ngay sau khi nộp." : "Start with the recommended diagnostic or take a short practice now. You will see your result immediately after submission."}</p>{query.error ? <p className="mt-5 rounded-xl bg-red-50 p-4 text-red-800" role="alert">{vi ? "Chưa thể tạo bài luyện. Vui lòng thử lại." : "Could not create practice. Please try again."}</p> : null}<section className="mt-8 grid gap-6 rounded-3xl bg-slate-900 p-6 text-white sm:p-8 lg:grid-cols-[1fr_auto] lg:items-center"><div><p className="text-sm font-black uppercase tracking-wider text-teal-300">{vi ? "Được đề xuất" : "Recommended"}</p><h2 className="mt-2 text-2xl font-black">{vi ? "Đánh giá nhanh Listening + Reading" : "Quick Listening + Reading diagnostic"}</h2><p className="mt-2 text-slate-300">{vi ? "Khoảng 24 câu · 15–20 phút · kết quả theo Part · đề xuất bài luyện tiếp theo." : "About 24 questions · 15–20 minutes · Part-level result · recommended next practice."}</p><p className="mt-3 text-xs text-slate-400">{vi ? "Độ chính xác thô; không phải điểm TOEIC chính thức hoặc dự đoán điểm." : "Raw accuracy; not an official TOEIC score or prediction."}</p></div><Link className="inline-flex min-h-12 items-center justify-center rounded-xl bg-teal-400 px-6 font-black text-slate-950" href="/diagnostic">{vi ? "Bắt đầu đánh giá" : "Start diagnostic"}</Link></section><section className="mt-6" id="quick-practice"><h2 className="text-xl font-black">{vi ? "Hoặc thử nhanh" : "Or try a shorter practice"}</h2><div className="mt-4 grid gap-5 sm:grid-cols-2">{choices.map(choice => <form action={startGuestPractice} className="rounded-3xl border border-slate-200 bg-white p-6 shadow-sm" key={choice.kind}><input name="kind" type="hidden" value={choice.kind}/><h3 className="text-2xl font-black">{choice.title}</h3><p className="mt-2 font-bold text-teal-700">{choice.meta}</p><p className="mt-3 leading-7 text-slate-600">{choice.body}</p><button className="mt-6 min-h-12 rounded-xl bg-teal-700 px-6 font-bold text-white focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-teal-700" type="submit">{vi ? "Bắt đầu ngay" : "Start now"}</button></form>)}</div></section></div><PublicFooter locale={locale} /></main>; }
